static int r8156_lock_main(struct r8152 *tp, bool lock)
{
	int i, ret;
	u16 data;

	if (lock)
		ret = ocp_reg_set_bits(tp, 0xa46a, BIT(1));
	else
		ret = ocp_reg_clr_bits(tp, 0xa46a, BIT(1));
	if (ret < 0)
		goto out;

	if (lock) {
		for (i = 0; i < 100; i++) {
			usleep_range(1000, 2000);
			ret = ocp_reg_read(tp, 0xa730, &data);
			if (ret < 0)
				goto out;
			data &= 0xff;
			if (data == 1)
				break;
		}
	} else {
		for (i = 0; i < 100; i++) {
			usleep_range(1000, 2000);
			ret = ocp_reg_read(tp, 0xa730, &data);
			if (ret < 0)
				goto out;
			data &= 0xff;
			if (data != 1)
				break;
		}
	}

	if (i == 100)
		ret = -ETIME;
	else
		ret = 0;

out:
	return ret;
}
